(function(){
  'use strict';
  const D=ApiManualData,$=id=>document.getElementById(id),N=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
  const main=$('content'),nav=$('nav'),search=$('search');$('version').textContent='v'+D.version;
  const guides=[{id:'intro',title:'API 이용방법'},{id:'auth',title:'인증·권한·중복 방지'},{id:'types',title:'업무별 전표 종류'},{id:'cross-reference',title:'이카운트 전체 대조표'},{id:'faq',title:'오류·제한·FAQ'}];
  const entries=[...guides.map(x=>({...x,group:'시작하기',kind:'guide'})),...D.endpoints.map(x=>({...x,kind:'api'})),...D.providers.map(x=>({...x,group:'이카운트 참조 · '+x.group,kind:'provider'}))];
  const link=(title,id)=>{const a=N('a',title);a.href='#'+id;return a;},external=(title,url)=>{const a=N('a',title);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;};
  function table(headers,rows){const w=N('div',undefined,'table-wrap'),t=N('table'),head=N('thead'),tr=N('tr'),body=N('tbody');headers.forEach(x=>{const th=N('th',x);th.scope='col';tr.append(th);});head.append(tr);for(const row of rows){const r=N('tr');for(const x of row){const c=N('td');c.append(x instanceof Node?x:document.createTextNode(x==null?'—':String(x)));r.append(c);}body.append(r);}t.append(head,body);w.append(t);return w;}
  function card(title,id){const s=N('section',undefined,'card');if(id)s.id=id;s.append(N('h2',title));main.append(s);return s;}
  const p=(s,text)=>s.append(N('p',text)),note=(s,text,warn=false)=>s.append(N('div',text,'callout'+(warn?' warning':'')));
  function chips(items){const w=N('div',undefined,'chips');for(const [text,cls]of items)w.append(N('span',text,'chip '+(cls||'')));main.append(w);}
  function code(s,title,value){const label=N('div',undefined,'code-head'),b=N('button','복사','copy'),text=typeof value==='string'?value:JSON.stringify(value,null,2);b.type='button';b.setAttribute('aria-label',title+' 복사');b.onclick=async()=>{try{await navigator.clipboard.writeText(text);b.textContent='복사 완료';}catch{b.textContent='본문에서 선택해 복사';}};label.append(N('span',title),b);s.append(label,N('pre',text));}
  function fields(s,title,rows){s.append(N('h3',title),rows.length?table(['변수','변수명','형식·범위','필수 여부','설명'],rows.map(x=>[x.name,x.label,x.type,x.required,x.description])):N('p','입력 변수 없음.'));}
  function quick(s,items){const w=N('div',undefined,'quick-links');for(const [title,id]of items)w.append(link(title,id));s.append(w);}
  const navEntries=[...new Set(entries.map(e=>e.group))].flatMap(g=>entries.filter(e=>e.group===g));
  function renderNav(){const q=search.value.trim().toLowerCase();nav.replaceChildren();let group='',count=0;for(const e of navEntries){const related=(e.peers||[]).map(id=>D.providers.find(p=>p.id===id).title).join(' ');const business=e.id==='documents-create'||e.id==='types'?D.documentTypes.flat().join(' '):'';const hay=[related,business,e.title,e.path||'',e.group,e.summary||'',...(e.request||[]).map(x=>x.name+' '+x.label),e.note||''].join(' ').toLowerCase();if(q&&!hay.includes(q))continue;count++;if(e.group!==group){group=e.group;nav.append(N('div',group,'group'));}const a=link(e.title,e.id);if(e.kind==='api'){const t=N('span',e.method,'nav-tag');a.append(t);}if(e.id===selected())a.setAttribute('aria-current','page');nav.append(a);}if(!count)nav.append(N('p','검색 결과가 없습니다.','no-results'));$('search-status').textContent=q?count+'개 문서 검색됨':'우리 API '+D.endpoints.length+'개 · 이카운트 참조 '+D.providers.length+'개';}
  function selected(){try{return decodeURIComponent(location.hash.slice(1))||'intro';}catch{return 'intro';}}
  function intro(){main.append(N('p','우리 업무 전체를 연결하는 API 설명서','lead'));const stats=N('div',undefined,'stats');for(const [n,label]of [[D.endpoints.length,'우리 API 전체'],[D.providers.length,'이카운트 대조 항목'],[D.documentTypes.length,'공통 전표 종류']]){const s=N('div',undefined,'stat');s.append(N('b',String(n)),N('span',label));stats.append(s);}main.append(stats);const start=card('업무에서 필요한 API를 찾아보세요');p(start,'기초등록부터 재고·전표·수신·송신, 키 관리와 자료 복사까지 실제 구현된 모든 HTTP API를 수록했습니다. 왼쪽 목차나 검색으로 상세 요청값·응답값·예제를 확인할 수 있습니다.');quick(start,[['인증부터 시작','auth'],['판매 전표 입력','documents-create'],['이카운트 기능 대조','cross-reference']]);note(start,'현재는 소유자 전용 가상 자료 검증 환경입니다. 문서를 읽거나 항목을 선택하는 동작으로 API를 실행하지 않습니다.');const step=card('연동 순서');const ol=N('ol');for(const t of ['소유자가 연동센터에서 서버 가상 자료·API 키·연결을 준비합니다.','호출 도구에 비공개 Sites 접근 자격과 필요한 앱 키 권한을 설정합니다.','품목·거래처·창고 코드를 조회하고 상대 ERP와 코드·필드·단위를 맞춥니다.','전표를 직접 입력하거나, 외부 이벤트 접수 → 업무 반영 순서로 처리합니다.','처리 상태와 재고 차이를 확인하고 송신 대기 작업을 명시적으로 전송합니다.'])ol.append(N('li',t));step.append(ol);const scope=card('문서 범위');scope.append(table(['구분','수록 범위'],[['업무·서비스 API','조회·신규 입력·수신·업무 반영·이력 15개'],['앱 관리자 API','운영 현황·키·연결·미리보기·대사·백업·복사·샘플 준비 11개'],['앱 계정·커스터마이징·고객 포털','10개 HTTP 동작 + 24개 설정·사용자·자료 작업'],['이카운트 OAPI 참조','사용자가 연 한국어 매뉴얼의 화면상 업무 항목 28개. 기능 대응·부분 대응·인증 개념 참조·미제공 구분.'],['우리 화면 기능과 API','우리 화면에 있어도 공개 HTTP 경로가 없는 기능은 제공 API로 표시하지 않습니다. 수정·삭제, 정식 회계·근태·게시판·A/S API 등은 미제공입니다.']]));p(scope,'이 설명서의 원본은 우리 서버의 실제 처리 경로입니다. 이카운트의 매뉴얼 구조를 참고했으며, 인증키·세션 주소·회사 자료를 포함하지 않습니다.');}
  function auth(){const s=card('앱 계정과 연동 키');const login=N('a','앱 로그인 화면 열기 ↗','button');login.href='/login';s.append(login);p(s,'ERP는 회사코드·앱 ID·비밀번호로 로그인합니다. 첫 접속에서 사이트 소유자가 첫 관리자 계정을 등록합니다. 이후 ChatGPT 접속 정보만으로 ERP 업무를 사용할 수 없습니다.');s.append(table(['방식','사용 규칙'],[['앱 로그인','POST /api/auth/login → HttpOnly 세션 쿠키. /api/auth/status에서 현재 사용자와 csrfToken을 확인합니다.'],['관리 API','앱 세션과 해당 사용자 권한이 필요합니다. 키 관리·연결은 integrations.manage, 업무 백업·가져오기는 data.manage 등.'],['브라우저 쓰기','같은 origin에서 JSON POST + X-CSRF-Token. 로그아웃·설정·관리·전표 쓰기 모두 적용합니다.'],['외부 업무 연동','X-Api-Key와 read/write/events:process 범위를 사용합니다. 앱 계정·설정 관리에는 키를 사용할 수 없습니다.'],['비공개 호스팅 접근','현재 검증 사이트는 소유자 전용입니다. 외부 호출은 Sites 접근 자격도 필요합니다. 앱 사용자 등록이 호스팅 공유 범위를 넓히지는 않습니다.'],['비밀번호·접속','해시 저장, 실패 제한, 활성/승인 상태, 세션 폐기와 IP 정책을 서버에서 검사합니다.']]));quick(s,[['앱 ID 로그인','auth-login'],['인증 상태','auth-status'],['API 키 발급','keys-create'],['설정 작업 전체','self-action']]);const r=card('요청 공통 규칙');r.append(table(['항목','규칙'],[['자료형식','POST는 Content-Type: application/json과 JSON 객체. 변수가 없으면 {}.'],['크기','업무 API 250KB, 앱 관리 API 450KB. 가져오기 텍스트 250KB 이하.'],['중복 방지','품목·거래처·전표·이벤트 신규 POST는 Idempotency-Key 필수.'],['설정 동시 수정','/api/self/action은 state 조회의 revision 필수. 새로 조회한 값으로만 저장합니다.'],['실패 처리','HTTP 오류의 error.code/message와 이벤트·송신의 본문 status를 각각 확인합니다.']]));code(r,'앱 세션으로 설정 저장','POST '+location.origin+'/api/self/action\nContent-Type: application/json\nX-CSRF-Token: <현재 user.csrfToken>\nCookie: 브라우저가 HttpOnly 세션을 자동 전달');}
  function types(){const s=card('20종 전표를 하나의 입력 API로');p(s,'POST /api/v1/documents의 type만 바꾸고 업무별 필수값을 채웁니다. 조회는 GET /api/v1/documents?type=종류를 사용합니다.');s.append(table(['type','업무명','추가 확인'],D.documentTypes.map(([id,title])=>[id,title,id==='transfer'?'targetWarehouse 필수 · 출발/도착 창고 구분':id==='production'?'autoConsume 사용 시 BOM·원재료 확인':id==='work'?'작업 시간 등 전용 필드는 API 미노출':['quote','order','sale','purchaseorder','purchase','shoporder'].includes(id)?'partner 필수':id==='adjust'?'수량 부호로 조정':id==='count'?'실사 수량 0 허용':'공통 코드·양식·재고 규칙 적용'])));quick(s,[['입력 변수 전체 보기','documents-create'],['전표 조회','documents-list']]);code(s,'창고이동 입력 예제',{type:'transfer',date:'2026-10-15',warehouse:'W001',targetWarehouse:'W002',lines:[{item:'P001',qty:1,price:12000}]});note(s,'전표 저장은 한 건 단위입니다. 같은 HTTP 요청으로 여러 전표를 일괄 저장하는 API는 없습니다. 업무 화면의 승인·마감·회계 확정·전체 옵션이 API로 모두 제공되지는 않습니다.');}
  function matching(){const s=card('이카운트 OAPI ↔ 우리 API');p(s,'기능을 대조하고 양쪽 문서 항목을 서로 찾아가는 표입니다. 기능 대응은 API 형식 호환이나 실 연동 완료를 의미하지 않습니다.');note(s,'이카운트 원본을 수정하는 기능이 아니라, 우리 매뉴얼 안에 양방향 참조를 제공합니다. 이카운트 문서는 원본 매뉴얼 링크에서 해당 목차를 선택하세요.');const controls=N('div',undefined,'match-select'),label=N('label','대조 범위 '),select=N('select');select.setAttribute('aria-label','대조 범위');for(const [v,t]of [['all','전체 28개'],['mapped','대응·부분 대응'],['missing','우리 API 미제공'],['auth','인증 개념 참조']]){const o=N('option',t);o.value=v;select.append(o);}label.append(select);controls.append(label);s.append(controls);const out=N('div');s.append(out);const draw=()=>{const rows=D.providers.filter(x=>select.value==='all'||select.value==='missing'&&!x.ours.length||select.value==='auth'&&x.status==='인증 개념 참조'||select.value==='mapped'&&x.ours.length&&x.status!=='인증 개념 참조');out.replaceChildren(table(['업무','이카운트 OAPI 문서','대응 구분','우리 API 문서','연동 시 확인'],rows.map(x=>{const links=N('div',undefined,'link-stack');x.ours.forEach(id=>links.append(link(D.endpoints.find(e=>e.id===id).title,id)));return [x.group,link(x.title,x.id),x.status,x.ours.length?links:'미제공',x.note];})));};select.onchange=draw;draw();p(s,'확인 기준: '+D.checkedAt+' · 로그인 후 열린 한국어 OAPI 매뉴얼의 표시 항목. 회사·언어·서비스 변경에 따라 원본은 달라질 수 있습니다.');s.append(external('이카운트 원본 API 매뉴얼 열기 ↗',D.officialManual));const ours=card('우리 전용 API도 빠짐없이');p(ours,'아래 API는 이카운트 매뉴얼의 28개 항목에 직접 대응하지 않아도 우리 연동 운영에 필요한 기능입니다.');const links=N('div',undefined,'link-stack');D.endpoints.filter(e=>!e.peers.length).forEach(e=>links.append(link(e.title,e.id)));ours.append(links);}
  function faq(){const s=card('공통 오류');s.append(table(['HTTP','code','확인할 내용'],D.errors));code(s,'오류 응답 예제',{error:{code:'idempotency_conflict',message:'같은 중복 방지 키에 다른 자료가 들어왔습니다.'}});const limits=card('현재 검증 환경의 보관 한도');limits.append(table(['항목','한도·동작'],[['전체 서버 JSON','1,500,000바이트'],['API 키 / 연결','50개 / 30개'],['중복 방지 이력 / 수신 이벤트','1,500개 / 300개'],['송신 대기·결과','200개. 가득 차면 신규 전표 차단. 미전송 작업을 버리지 않습니다.'],['이력 / API 조회','300개 보관, 로그 API 최신 100개·운영 현황 60개'],['수신 처리 / 송신 시도','각 작업 최대 5회'],['전표 / 재고 대사','품목 행 1~100개 / 상대 재고 최대 10,000행']]));const q=card('자주 묻는 질문');for(const [title,body]of [['문서를 열면 전표가 생성되나요?','아니요. 매뉴얼은 정적 설명서입니다. 요청 시험은 연동센터에서 요청 실행 버튼을 눌렀을 때만 실행합니다.'],['HTTP 200이면 업무가 끝났나요?','이벤트는 status가 done인지, 송신은 result.status가 sent인지 확인합니다. internalTest가 true이면 서버 내부 시험입니다.'],['우리 ERP 화면의 모든 기능이 API인가요?','화면 기능과 HTTP API는 별개입니다. 이 문서는 실제 제공하는 36개 API와 24개 설정 작업을 다룹니다. 아직 경로가 없는 기능을 제공한다고 표시하지 않습니다.'],['이카운트로 바로 보내면 되나요?','현재 송신 구조는 우리 공통 이벤트입니다. 이카운트의 Zone·로그인 세션·업무별 구조·필드·날짜·코드 변환을 담당할 어댑터가 필요합니다. 원본으로 실 송신한 상태는 아닙니다.'],['브라우저와 API 자료가 다른 이유는?','재고 화면은 브라우저 저장소, API는 서버 DB를 사용합니다. 자료 복사 미리보기와 수정 번호 확인을 거쳐 명시적으로 옮깁니다.'],['이카운트 버튼을 누르면 같은 항목이 바로 열리나요?','원본 매뉴얼은 세션과 내부 목차 선택을 사용합니다. 인증 정보 없는 원본 시작 주소로 연결하므로 로그인 후 해당 목차를 선택할 수 있습니다. 우리 매뉴얼 내의 대조 항목은 직접 이동합니다.']]){q.append(N('h3',title),N('p',body));}}
  function endpoint(e){chips([[e.scope==='owner'?'앱 관리자 API':'업무·서비스 API',e.scope==='owner'?'amber':'green'],['권한: '+(e.scope==='owner'?'앱 관리자 로그인':e.scope),'blue'],[e.idempotent?'중복 방지 키 필수':'Idempotency-Key 불필요','']]);const overview=card('개요');p(overview,e.summary);if(e.notes)for(const n of e.notes)p(overview,n);const ref=card('이카운트 대조 참조');if(e.peers.length){for(const id of e.peers){const peer=D.providers.find(x=>x.id===id),r=N('div',undefined,'reference-row');r.append(link(peer.title+' → 대조 상세',id),N('span',' · '+peer.status,'small'),N('p',peer.note));ref.append(r);}}else p(ref,'우리 전용 기능입니다. 확인한 이카운트 OAPI 28개 항목에 직접 대응하는 공개 항목이 없습니다.');quick(ref,[['전체 대조표','cross-reference']]);const req=card('요청 데이터 형식');const path=e.path+(e.queryExample||'');const line=N('div',undefined,'endpoint');line.append(N('span',e.method,'method '+e.method.toLowerCase()),document.createTextNode(path));req.append(line,table(['항목','설명'],[['호출방식',e.method],['Content-Type',e.method==='POST'?'application/json':'요청 본문 없음'],['Request URL',location.origin+path],['인증',['public','bootstrap'].includes(e.scope)?'로그인 전용 / 최초 소유자 등록':e.scope==='owner'||e.scope==='app'?'앱 세션 + 해당 권한. POST에 X-CSRF-Token':'앱 세션 또는 비공개 Sites 접근 자격 + X-Api-Key'],['권한',e.scope==='owner'?'owner':e.scope],['Idempotency-Key',e.idempotent?'필수 · 최대 120자':'불필요'],['자료형식','JSON']]));fields(req,'자료포맷 종류 · Parameter',e.request);if(e.actions){const actions=card(e.actionTitle||'전체 설정 작업 · action 대조');actions.append(table(['action','서버 권한','payload 필드','동작'],e.actions));p(actions,e.actionHelp||'각 설정의 실제 값은 /api/self/state의 config에서 조회한 구조로 전달합니다. 비밀번호 변경·관리자 해제는 기존 세션에도 즉시 적용됩니다.');}const res=card('Result · 응답 변수');fields(res,'정상 응답',e.response);const ex=card('Example Parameter · 요청 예제');let h=e.method+' '+location.origin+path;if(e.method==='POST')h+='\nContent-Type: application/json';h+=['public','bootstrap'].includes(e.scope)?'\nOrigin: '+location.origin:e.scope==='owner'||e.scope==='app'?'\n인증: 앱 세션\nX-CSRF-Token: <현재 user.csrfToken>':'\nX-Api-Key: <발급한 앱 키>\nOAI-Sites-Authorization: Bearer <Sites 접근 자격>';if(e.idempotent)h+='\nIdempotency-Key: EXT-'+e.id.toUpperCase()+'-001';code(ex,'호출 정보',h);if(e.example!==null)code(ex,'요청 본문',e.example);code(ex,'Example Result · 응답 예제',e.result);p(ex,'모든 예제는 합성 자료이며 실제 호출 결과가 아닙니다. <…> 및 대문자 ID는 발급·조회한 값으로 바꾸세요. 백업 예제는 별도 안내를 확인하세요.');const err=card('오류 종류별 설명');err.append(table(['HTTP','주요 코드','설명'],D.errors));quick(err,[['인증·공통 규칙','auth'],['한도·FAQ','faq']]);const tools=card('직접 시험');const a=N('a','연동센터에서 요청 시험 열기 ↗','button');a.href='/?apiView=test#menu=1-0-2';tools.append(a);p(tools,'이동만으로 실행되지 않습니다. 소유자가 대상·본문·키를 확인하고 요청 실행을 눌러 시험합니다.');}
  function provider(e){chips([['이카운트 원본 참조','blue'],[e.status,e.ours.length?'green':'amber'],['확인 '+D.checkedAt,'']]);const s=card('기능 대응');p(s,e.note);note(s,'원본 매뉴얼에서 확인한 기능명·호출 방식·세션 쿼리를 제외한 경로만 정리했습니다. 아래 링크는 우리 문서의 대응 항목입니다. 형식 호환·자동 연동 완료를 뜻하지 않습니다.');s.append(table(['항목','내용'],[['제공자','이카운트'],['업무',e.group],['호출 방식',e.method],['원본 요청 경로',e.path],['인증','Zone·로그인 API를 거쳐 받은 세션. 세부 항목은 원본 매뉴얼 확인.'],['원본 문서',external('이카운트 API 매뉴얼 ↗',D.officialManual)]]));const ours=card('대응하는 우리 API');if(e.ours.length)for(const id of e.ours){const a=D.endpoints.find(x=>x.id===id),r=N('div',undefined,'reference-row');r.append(link(a.title+' → 우리 요청·응답 보기',id),N('p',a.method+' '+a.path));ours.append(r);}else note(ours,'대응하는 우리 HTTP API는 아직 없습니다. 위 업무가 필요하면 해당 업무 모델과 API를 추가해야 합니다.',true);if(e.id==='ecount-sale'){const map=card('판매 필드 대조 · 변환 설계 참고');map.append(table(['이카운트 판매 변수','우리 전표 변수','변환·확인'],D.salesMapping));p(map,'원본 판매 자료의 SaleList[].BulkDatas 반복 행을 우리 lines[]로 묶고 type=sale을 정합니다. 이 표는 의미 대응입니다. 현재 수신 매핑 설정은 값의 날짜 변환·행별 키 변환·배열 묶기를 실행하지 않으므로 전처리 어댑터가 필요합니다.');code(map,'우리 판매 입력 예제',D.sampleDocument);}const caution=card('연동 시 확인');const ul=N('ul');for(const t of ['인증 방식, 호출 Method, 날짜·숫자 형식, 코드·단위, 회사별 입력양식 필수 항목을 확인합니다.','우리 응답은 소문자 필드 중심의 JSON이며 이카운트의 Status·Error·성공/실패 건수 구조와 다릅니다. HTTP 상태와 본문 업무 상태를 각각 확인합니다.','우리 문서의 중복 방지 키·조회 범위·보관 한도를 원본 ERP 규칙으로 그대로 적용하지 않습니다.','실 이카운트로 호출하거나 API 인증키를 발급한 검증은 하지 않았습니다.'])ul.append(N('li',t));caution.append(ul);quick(caution,[['전체 대조표','cross-reference'],['연결 설정의 지원 범위','profiles-create']]);}
  function render(){const id=selected(),e=entries.find(x=>x.id===id);main.replaceChildren();main.append(N('div',e?e.group:'문서 찾기','breadcrumb'),N('div','AUTOMATION ERP · API MANUAL','eyebrow'),N('h1',e?e.title:'문서를 찾을 수 없습니다'));document.title=(e?e.title:'API 매뉴얼')+' · 자동화 ERP';if(!e){p(main,'목차에서 문서를 선택하거나 검색해 주세요.');quick(main,[['API 이용방법','intro']]);}else if(e.kind==='api')endpoint(e);else if(e.kind==='provider')provider(e);else ({intro,auth,types,'cross-reference':matching,faq})[id]();main.append(N('p','API 매뉴얼 v'+D.version+' · '+D.checkedAt+' 기준 · 가상 자료 검증 환경','footer-note'));renderNav();window.scrollTo(0,0);}
  document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();main.focus();});
  search.addEventListener('input',renderNav);window.addEventListener('hashchange',render);render();
})();
